#!/usr/bin/env python3
r"""C495 independent replay.

Re-derives the load-bearing C495 facts with independent code and asserts agreement with the
committed certificate notes/2026-07-22-c495-cloud-packet-d10-identification.json:

  * PGL_2(11) is regenerated by generator closure (not the primary checker's exhaustive tuple
    enumeration); order 1320 is confirmed.
  * the conic cell action (symmetric square), the intrinsic edge coordinate u = XZ/Y^2, and the
    determinant square test are reimplemented from scratch here.
  * the setwise stabilizer of C80's 22-move set is recomputed with this independent group and
    action: order 5, zero determinant-nonsquare elements (no internal D10).
  * the C5-orbit profile and the u square-class 5-orbit split are recomputed by union-find.
  * the C434 D10 side profile and sheet 2-2 split are recomputed by union-find on the frozen
    matching constructors.

The underlying residual-grid legality (the 22-move object) and the C434 matching geometry are
each independently replayed by their own committed bundles
(rust/scripts/c80_c447_cloud_packet_replay.py and
notes/2026-07-22-c434-double-coset-information-lattice-replay.py), which C495 consumes and hashes.

Run from /home/tavis/src/othello:
    python3 rust/scripts/c495_cloud_packet_d10_identification_replay.py
"""
from __future__ import annotations

import importlib.util
import json
import sys
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
CERT = ROOT / "notes/2026-07-22-c495-cloud-packet-d10-identification.json"
C447_JSON = ROOT / "notes/2026-07-21-c447-cap-knife-edge.json"
C20_SOURCE = ROOT / "notes/2026-07-08-intrusion-census.py"
C434_PATH = ROOT / "notes/2026-07-22-c434-double-coset-information-lattice.py"
Q = 11


# ---- independent finite-field / projective helpers (reimplemented, not imported) ----------
def inv(x):
    return pow(x % Q, Q - 2, Q)


def normalize(v):
    pivot = next(x for x in v if x % Q)
    s = inv(pivot)
    return tuple(x * s % Q for x in v)


def matvec(m, v):
    return tuple(sum(m[i][j] * v[j] for j in range(3)) % Q for i in range(3))


def matmul2(a, b):
    return (
        (a[0] * b[0] + a[1] * b[2]) % Q,
        (a[0] * b[1] + a[1] * b[3]) % Q,
        (a[2] * b[0] + a[3] * b[2]) % Q,
        (a[2] * b[1] + a[3] * b[3]) % Q,
    )


def norm2(m):
    piv = next(x for x in m if x % Q)
    s = inv(piv)
    return tuple(x * s % Q for x in m)


def det_is_square(m):
    a, b, c, d = m
    det = (a * d - b * c) % Q
    return pow(det, (Q - 1) // 2, Q) == 1


def sym_square(m):
    a, b, c, d = m
    return [
        [d * d % Q, 2 * c * d % Q, c * c % Q],
        [b * d % Q, (a * d + b * c) % Q, a * c % Q],
        [b * b % Q, 2 * a * b % Q, a * a % Q],
    ]


def standard_point(w):
    return (0, 0, 1) if w == "inf" else (1, w % Q, w * w % Q)


def cap_cell(matrix, point):
    image = normalize(matvec(matrix, point))
    assert image[2] != 0
    s = inv(image[2])
    return (image[0] * s % Q, image[1] * s % Q)


def cap_cell_action(record, m, cell):
    standard = matvec(record["cap_to_standard_projectivity"], (cell[0], cell[1], 1))
    image = matvec(sym_square(m), standard)
    return cap_cell(record["standard_to_cap_projectivity"], image)


def edge_quotient_u(record, endpoints, cell):
    a, b = endpoints
    normalizer = (1, -a % Q, 1, -b % Q)
    standard = matvec(record["cap_to_standard_projectivity"], (cell[0], cell[1], 1))
    x, y, z = normalize(matvec(sym_square(normalizer), standard))
    return "inf" if y == 0 else x * z * inv(y * y % Q) % Q


def generate_pgl2():
    gens = [(1, 1, 0, 1), (2, 0, 0, 1), (0, 1, 1, 0)]  # x+1, 2x, 1/x
    seen = {(1, 0, 0, 1)}
    frontier = [(1, 0, 0, 1)]
    while frontier:
        nxt = []
        for g in frontier:
            for h in gens:
                p = norm2(matmul2(g, h))
                if p not in seen:
                    seen.add(p)
                    nxt.append(p)
        frontier = nxt
    return sorted(seen)


def union_find_orbits(elements, act):
    elems = list(elements)
    index = {e: i for i, e in enumerate(elems)}
    seen, orbits = set(), []
    for e in elems:
        if e in seen:
            continue
        orbit, stack = set(), [e]
        while stack:
            cur = stack.pop()
            if cur in orbit:
                continue
            orbit.add(cur)
            for img in act(cur):
                if img not in orbit:
                    stack.append(img)
        seen |= orbit
        orbits.append(frozenset(orbit))
    return orbits


def load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return module


def main():
    cert = json.loads(CERT.read_text())
    group = generate_pgl2()
    assert len(group) == Q * (Q * Q - 1) == 1320, f"group order {len(group)}"

    # residual-grid legality engine (the 22-move object; geometry validated by its own bundle)
    game_module = load("c495_game", C20_SOURCE)
    game = game_module.PrimeGridGame(Q)
    source = json.loads(C447_JSON.read_text())

    squares = {v * v % Q for v in range(1, Q)}

    def sqclass(u):
        if u == "inf":
            return "inf"
        if u == 0:
            return "zero"
        return "sq" if u in squares else "nonsq"

    for record in source["knife_edge_classes"]:
        repair = record["canonical_shared_edge_cross_sheet_pair"]
        matrix = record["standard_to_cap_projectivity"]
        endpoints = repair["shared_p_edge"]
        frame = set(record["frame_parameters"])

        # independent cap-frame stabilizer via the reimplemented Mobius action on parameters
        def mobius(m, x):
            a, b, c, d = m
            if x == "inf":
                return "inf" if c == 0 else a * inv(c) % Q
            den = (c * x + d) % Q
            return "inf" if den == 0 else (a * x + b) * inv(den) % Q

        frame_stab = [g for g in group if {mobius(g, x) for x in frame} == frame]
        square_kernel = [g for g in frame_stab if det_is_square(g)]

        for endpoint_index, endpoint in enumerate(endpoints):
            witness = cap_cell(matrix, standard_point(endpoint))
            seed = [tuple(cell) for cell in record["S3"]] + [witness]
            mask = sum(game.bit_for_cell(cell) for cell in seed)
            moves = {game.cell_tuple(idx) for _b, idx in game.iter_bits(game.legal_mask(mask))}
            assert len(moves) == 22

            # C5-orbit profile (union-find, independent action)
            c5_orbits = union_find_orbits(
                moves, lambda cell: {cap_cell_action(record, g, cell) for g in square_kernel}
            )
            assert sorted(len(o) for o in c5_orbits) == [1, 1, 5, 5, 5, 5]

            # full setwise stabilizer in the regenerated PGL_2(11)
            stab_order, stab_nonsquare = 0, 0
            for g in group:
                try:
                    image = {cap_cell_action(record, g, cell) for cell in moves}
                except AssertionError:
                    continue
                if image == moves:
                    stab_order += 1
                    if not det_is_square(g):
                        stab_nonsquare += 1
            assert stab_order == 5 and stab_nonsquare == 0, (stab_order, stab_nonsquare)

            # u square-class split of the four 5-orbits
            five = Counter(
                sqclass(edge_quotient_u(record, endpoints, min(o)))
                for o in c5_orbits
                if len(o) == 5
            )
            assert sorted(five.values()) != [2, 2], five  # not a 2-2 sheet-sign split

    # ---- C434 D10 side (union-find on frozen matching constructors) ----
    c434 = load("c495_c434r", C434_PATH)
    scout = json.loads(c434.SCOUT_PATH.read_text())
    rec = next(r for r in scout["types"] if r["type"] == "H3")
    _, parameters = c434.C406.C399.conic_parameterization(Q)
    full_group, psl_group = c434.C406.full_pgl(Q, parameters)
    base = tuple(tuple(pair) for pair in rec["coxeter_invariant_matching"])
    omega = sorted({c434.matching_image(g, base) for g in full_group})
    plus_sheet = {c434.matching_image(g, base) for g in psl_group}
    psl_set = set(psl_group)
    stab_m0 = frozenset(g for g in full_group if c434.matching_image(g, base) == base)
    d10 = None
    for cand in sorted(g for g in full_group if g not in psl_set and c434.perm_order(g) == 2):
        mate = c434.matching_image(cand, base)
        stab_mate = frozenset(g for g in full_group if c434.matching_image(g, mate) == mate)
        k = stab_m0 & stab_mate
        if len(k) == 10:
            d10 = k
            break
    assert d10 is not None
    korbits = union_find_orbits(
        omega, lambda m: {c434.matching_image(g, m) for g in d10}
    )
    assert sorted(len(o) for o in korbits) == [1, 1, 5, 5, 5, 5]
    def sheet(m):
        return 0 if m in plus_sheet else 1

    five_sheets = Counter(sheet(next(iter(o))) for o in korbits if len(o) == 5)
    assert sorted(five_sheets.values()) == [2, 2], five_sheets  # sheet DOES give the 2-2 split

    # ---- cross-check against the committed certificate ----
    findings = cert["findings"]
    assert findings["c5_set_isomorphic"] is True
    assert findings["c80_setwise_stabilizer_is_exactly_c5"] is True
    assert findings["c80_packet_has_internal_d10"] is False
    assert findings["d10_or_g_equivariant_identification_holds"] is False
    assert findings["u_square_class_equals_sheet_sign"] is False
    assert findings["c434_omega_is_internal_d10_set"] is True
    assert cert["verdict"].startswith("FALSIFIER_NO")

    print("C495 independent replay: PASS "
          "(C5-set iso YES; internal-D10 / G-equivariant identification NO; u != sheet sign)")


if __name__ == "__main__":
    main()
